def construir_coleccion(resultados):
    ids={}
    items=[]
    for r in resultados:
        n=r['numero'];body=r['peticion'];url=r['ruta']
        for valor,variable in ids.items():url=url.replace(valor,'{{'+variable+'}}')
        request={'method':r['metodo'],'header':[],'url':('{{baseExterna}}' if 22<=n<=25 else '{{baseUrl}}')+url}
        auth=r['auth']
        request['auth']={'type':'noauth'} if not auth else {'type':'bearer','bearer':[{'key':'token','value':'invalido' if auth=='invalid' else '{{tokenVencido}}' if auth=='expired' else '{{token}}','type':'string'}]}
        if body is not None:
            body=json.loads(json.dumps(body))
            if n in (3,26):body={'usuario':'{{usuario}}','contrasena':'{{contrasena}}'}
            for k,v in body.items():
                if isinstance(v,str) and v in ids:body[k]='{{'+ids[v]+'}}'
            request['header']=[{'key':'Content-Type','value':'application/json'}]
            request['body']={'mode':'raw','raw':json.dumps(body,ensure_ascii=False,indent=2),'options':{'raw':{'language':'json'}}}
        assertions=[f"pm.test('HTTP {r['esperado']}',()=>pm.response.to.have.status({r['esperado']}));",r['checks']]
        if n in (3,26):assertions.append("pm.collectionVariables.set('token',pm.response.json().token);")
        variable={6:'idGenero',10:'idLibro',30:'idGenero',33:'idOtroGenero'}.get(n)
        if variable:
            ids[r['respuesta']['datos']['_id']]=variable
            assertions.append(f"pm.collectionVariables.set('{variable}',pm.response.json().datos._id);")
        request['description']=f"Caso {n}: {r['titulo']}. Estado esperado {r['esperado']}. "+('Proveedor simulado.' if 22<=n<=25 else 'API real; ver reporte para condiciones y propósito.')
        response={'name':f"Ejemplo observado HTTP {r['estado']}",'originalRequest':request,'status':str(r['estado']),'code':r['estado'],'header':[{'key':'Content-Type','value':'application/json'}],'body':json.dumps(r['respuesta'],ensure_ascii=False,indent=2)}
        items.append({'name':f'{n:02d}. {r["titulo"]}','request':request,'response':[response],'event':[{'listen':'test','script':{'type':'text/javascript','exec':assertions}}]})
    return {'info':{'name':'Lumbre — Entrega SDD — 51 pruebas','schema':'https://schema.getpostman.com/json/collection/v2.1.0/collection.json','description':'Contrato: docs/ESPECIFICACION-SDD.md. 51 solicitudes y 102 aserciones; 22–25 proveedor simulado; 50–51 Open Library real. Seguir reporte/LEEME.txt.'},'variable':[{'key':k,'value':v,'type':'string'} for k,v in [('baseUrl','http://127.0.0.1:8031'),('baseExterna','http://127.0.0.1:8032'),('usuario','practica'),('contrasena','PracticaCRUD2026!'),('token',''),('tokenVencido',''),('idGenero',''),('idLibro',''),('idOtroGenero','')]],'item':items}
